/**
 * Deteksi rekomendasi KBLI cerdas berdasarkan data empiris SE2026 BPS Kabupaten Mempawah
 */
export const getKbliSuggestionFromBusinessName = (rawName: string | null | undefined): KbliSuggestion | null => {
  if (!rawName) return null;
  
  // Bersihkan teks (abaikan nama orang di dalam tanda kurung / kurung siku)
  const clean = rawName
    .replace(/\(.*?\)|<.*?>|\[.*?\]/g, ' ')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  if (clean.length < 2) return null;

  // 1. Prioritas Utama: Evaluasi frasa majemuk terlatih (paling spesifik terlebih dahulu)
  for (let i = 0; i < SE2026_TRAINED_PHRASES.length; i++) {
    const [phrase, katKode, kbli5, cnt] = SE2026_TRAINED_PHRASES[i];
    // Gunakan word boundary check untuk menghindari false match (misal: 'kuliner' tidak boleh kena 'kuli')
    if (clean === phrase || clean.includes(' ' + phrase) || clean.includes(phrase + ' ') || clean.includes(' ' + phrase + ' ') || clean.startsWith(phrase) || clean.endsWith(phrase)) {
      const cat = KATEGORI_LAPANGAN_USAHA.find(k => k.kode === katKode);
      if (cat) {
        return {
          kode: cat.kode,
          nama: cat.nama,
          singkat: cat.singkat,
          kbli5Digit: kbli5 || undefined,
          matchedKeyword: phrase,
          min: cat.min,
          max: cat.max,
          count: cnt
        };
      }
    }
  }

  // 2. Evaluasi kata tunggal / token (dengan word boundary tepat)
  const words = clean.split(' ').filter(w => w.length >= 2);
  for (let i = 0; i < SE2026_TRAINED_TOKENS.length; i++) {
    const [token, katKode, kbli5, cnt] = SE2026_TRAINED_TOKENS[i];
    // Pastikan kata cocok secara utuh atau merupakan awalan kata dasar (stem >= 4 huruf)
    const isMatched = words.some(w => w === token || (token.length >= 4 && (w.startsWith(token) || token.startsWith(w))));
    if (isMatched) {
      const cat = KATEGORI_LAPANGAN_USAHA.find(k => k.kode === katKode);
      if (cat) {
        return {
          kode: cat.kode,
          nama: cat.nama,
          singkat: cat.singkat,
          kbli5Digit: kbli5 || undefined,
          matchedKeyword: token,
          min: cat.min,
          max: cat.max,
          count: cnt
        };
      }
    }
  }

  return null;
};
